"""Regression test generated by Night Watch from INC-0014.

It replays the real request that broke the "OWNERSHIP" invariant on /bank/v2/transfers.
It must fail on the vulnerable code and pass once the root cause is fixed. Do not weaken it.
"""
from datetime import datetime

from oasis.bank import Bank

NOW = datetime.fromisoformat("2026-11-21T21:06:00")


def _login(bank, customer_id, device):
    pw = bank.customers[customer_id]["password_demo"]
    status, body = bank.handle("POST", "/bank/login", {"x-device-id": device},
                               {"customer_id": customer_id, "password": pw}, NOW)
    assert status == 200
    return body["token"]


def test_inc_0014_replayed_attack_is_refused():
    bank = Bank()
    token = _login(bank, "C012", "dev-8be7f932")
    victim_before = bank.accounts["0000000048239595"]["balance"]
    status, _ = bank.handle("POST", "/bank/v2/transfers", {"authorization": "Bearer " + token},
                            {"from_account": "0000000048239595", "to_iban": "AE239990000000048295028", "amount": 4900, "reference": "refund"}, NOW)
    assert status in (401, 403, 404, 422), "the bank accepted the replayed attack"
    assert bank.accounts["0000000048239595"]["balance"] == victim_before
    assert all(bank.accounts[e.from_account]["owner"] == e.principal for e in bank.journal)


def test_inc_0014_legitimate_use_still_works():
    bank = Bank()
    token = _login(bank, "C012", "dev-8be7f932")
    own = bank.customers["C012"]["accounts"][0]
    payee = next(a["iban"] for a in bank.accounts.values() if a["owner"] not in ("C012", "P001"))
    status, body = bank.handle("POST", "/bank/v2/transfers", {"authorization": "Bearer " + token},
                               {**{"from_account": "0000000048239595", "to_iban": "AE239990000000048295028", "amount": 4900, "reference": "refund"}, "from_account": own, "to_iban": payee, "amount": 10}, NOW)
    assert status == 200, body
